        }
      }
      return output;
    }

    return {
      redactString,
      redactValue,
      get count() {
        return count;
      },
    };
  }

  function escapeRegex(value) {
    return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

